import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Inline CUDA source for sum-reduction along dimension=1 (for 3D tensors: [B, D1, D2])
reduce_sum_source = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

__global__ void reduce_sum_dim1_kernel(const float* __restrict__ inp,
                                       float* __restrict__ out,
                                       const int B, const int D1, const int D2) {
    // Each block handles a single batch index b in x-dimension
    // The thread index handles D2 in 1D range
    int b = blockIdx.x;
    int d2 = threadIdx.x + blockIdx.y * blockDim.x;
    if (d2 < D2) {
        float sum_val = 0.0f;
        int base_idx = b * D1 * D2 + d2; 
        for (int d1 = 0; d1 < D1; d1++) {
            sum_val += inp[base_idx + d1 * D2];
        }
        out[b * D2 + d2] = sum_val;
    }
}

torch::Tensor reduce_sum_cuda(torch::Tensor x, int dim) {
    // Only handle 3D with dimension=1 for this example
    TORCH_CHECK(x.dim() == 3, "Expecting 3D tensor");
    TORCH_CHECK(dim == 1, "This custom kernel supports reducing along dim=1 only.");

    const auto B = x.size(0);
    const auto D1 = x.size(1);
    const auto D2 = x.size(2);

    auto opts = x.options();
    auto out = torch::zeros({B, 1, D2}, opts);

    // Prepare kernel launch
    const int threads = 256;
    dim3 block(threads);
    dim3 grid(B, (D2 + threads - 1) / threads);

    reduce_sum_dim1_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        B,
        D1,
        D2
    );

    return out;
}
'''

reduce_sum_cpp_source = r'''
torch::Tensor reduce_sum_cuda(torch::Tensor x, int dim);
'''

# Compile the inline CUDA code
reduce_sum = load_inline(
    name="reduce_sum",
    cpp_sources=reduce_sum_cpp_source,
    cuda_sources=reduce_sum_source,
    functions=["reduce_sum_cuda"],
    verbose=False,
)

############################################
# New Model Class That Uses Custom CUDA Sum
############################################
class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.reduce_sum = reduce_sum

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.reduce_sum.reduce_sum_cuda(x, self.dim)
